def compute(panel):
    out = {}
    for code in panel.codes():
        hs = panel.highs(code)
        cs = panel.closes(code)
        os_ = panel.open_today.get(code)
        hi = panel.high_today.get(code)
        lo = panel.low_today.get(code)
        cl = panel.close.get(code)
        if os_ is None or hi is None or lo is None or cl is None:
            continue
        if len(hs) < 6 or len(cs) < 6:
            continue
        shadow_sum = 0.0
        cnt = 0
        n = len(hs)
        for i in range(n - 5, n):
            h = hs[i]
            c = cs[i]
            if h is None or c is None or c <= 0:
                continue
            shadow_sum += (h - c) / c * 100.0
            cnt += 1
        if cnt < 3:
            continue
        avg_shadow = shadow_sum / cnt
        rng = hi - lo
        if rng <= 0:
            pos = 50.0
        else:
            pos = (cl - lo) / rng * 100.0
        out[code] = avg_shadow * (pos / 100.0)
    return out

def compute(panel):
    out = {}
    for code in panel.codes():
        hs = panel.highs(code)
        ls = panel.lows(code)
        cs = panel.closes(code)
        n = len(cs)
        if n < 31:
            out[code] = 0.0
            continue
        amp10 = 0.0
        for i in range(n - 10, n):
            if ls[i] > 0:
                amp10 += (hs[i] - ls[i]) / ls[i]
        amp10 = amp10 / 10.0
        amp30 = 0.0
        for i in range(n - 30, n):
            if ls[i] > 0:
                amp30 += (hs[i] - ls[i]) / ls[i]
        amp30 = amp30 / 30.0
        if amp30 <= 0:
            out[code] = 0.0
            continue
        comp = amp10 / amp30
        up_share = 0.0
        for i in range(n - 10, n):
            rng = hs[i] - ls[i]
            if rng > 0:
                up_share += (cs[i] - ls[i]) / rng
        up_share = up_share / 10.0
        out[code] = (1.0 - comp) * 100.0 + up_share * 10.0
    return out

